body:
We don't need to use native structs to solve the issue for C#, a normal RefCounted class would work as well. 

The caller would pass an already instantiated object and the method implementation would fill it, like the current `_intersect_ray` method does with `Dictionary`, except `_intersect_ray` creates a new `Dictionary` instance and the new method would reuse the instance provided by a parameter, and we could use a custom class instead of a `Dictionary` so it's more convenient.

For example:

```c++
class PhysicsServer3DRayResult : RefCounted {
    GDCLASS(PhysicsServer3DRayResult, RefCounted);

    Vector3 position;
    Vector3 normal;
    RID rid;
    ObjectID collider_id;
    Object *collider = nullptr;
    int shape = 0;
    int face_index = -1;

    void _bind_methods() {
        ADD_PROPERTY(PropertyInfo(Variant::VECTOR3, "position"), "set_position", "get_position");
        ADD_PROPERTY(PropertyInfo(Variant::VECTOR3, "normal"), "set_normal", "get_normal");
        ADD_PROPERTY(PropertyInfo(Variant::RID, "rid"), "set_rid", "get_rid");
        ADD_PROPERTY(PropertyInfo(Variant::OBJECT, "collider"), "set_collider", "get_collider");
        ADD_PROPERTY(PropertyInfo(Variant::INT, "shape"), "set_shape", "get_shape");
        ADD_PROPERTY(PropertyInfo(Variant::INT, "face_index"), "set_face_index", "get_face_index");
    }
}

bool PhysicsDirectSpaceState3D::_intersect_ray2(const Ref<PhysicsRayQueryParameters3D> &p_ray_query, Ref<PhysicsServer3DRayResult> r_result) {
    ERR_FAIL_COND_V(p_ray_query.is_null(), false);
    ERR_FAIL_COND_V(r_result.is_null(), false);

    RayResult result;
    bool res = intersect_ray(p_ray_query->get_parameters(), result);

    if (!res) {
        return false;
    }

    r_result.position = result.position;
    r_result.normal = result.normal;
    r_result.face_index = result.face_index;
    r_result.collider_id = result.collider_id;
    r_result.collider = result.collider;
    r_result.shape = result.shape;
    r_result.rid = result.rid;

    return true;
}
```

Binding this method should make it available for scripting languages like GDScript and for GDExtension bindings.
